import React from 'react';
import Card from '../components/Card';

const DashboardPage = () => {
  return (
    <div>
      <h1>Dashboard</h1>
      <Card>
        <h2>Your Progress</h2>
        <p>Track your resume analysis and interview preparation.</p>
      </Card>
    </div>
  );
};

export default DashboardPage;
